class DRW_Coord {
public:
    DRW_Coord()=default;
    DRW_Coord(double ix, double iy): x(ix), y(iy){}
    DRW_Coord(double ix, double iy, double iz): x(ix), y(iy),z(iz){}

    void unitize(){
#if __cplusplus < 201703
        double dist = std::hypot(std::hypot(x, y), z);
#else
        double dist = std::hypot(x, y, z);
#endif
        if (std::isnormal(dist)) {
            x= x/dist;
            y= y/dist;
            z= z/dist;
        }
    }

public:
    double x{0};
    double y{0};
    double z{0};
};

